mapper.select:
SELECT * FROM ( SELECT CC.*, CV.ConstrValDesc AS CustConsltTypeName, CR.ConstrValDesc AS CustConsltReasonTypeName, CM.ConstrValDesc AS ConsltMediaTypeName, P.ProdName, P.ImgUrl50 AS ProdImg, P.ShopName, P.ShopProdCode, Ch.ChnlName FROM shopion.tOprCustConslt CC INNER JOIN shopion.tStrChnl Ch ON Ch.ChnlCode = CC.ChnlCode
LEFT OUTER JOIN wizardn.tCodConstrVal CR ON CC.CustConsltReasonType = CR.ConstrVal AND CR.ConstrCode = 'cCustConsltReasonType' LEFT OUTER JOIN wizardn.tCodConstrVal CM ON CC.ConsltMediaType = CM.ConstrVal AND CM.ConstrCode = 'cConsltMediaType' LEFT OUTER JOIN shopion.tPrdProd P ON CC.ProdCode = P.ProdCode
) tab1
ORDER BY ${sidx} ${sord} ORDER BY CustConsltNo DESC
LIMIT #{topCnt}, #{countPerPage}

mapper.update:
UPDATE shopion.tOprCustConslt SET
MngrId = #{mngrId}, MngrName = #{mngrName}, MngrEmail = #{mngrEmail}, ProdCode = #{prodCode},
AnswrTitle = #{answrTitle}, AnswrCntnts = #{answrCntnts}, AnswrDate = NOW(),
State = #{state}, Remark = #{remark}, ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE CustConsltNo = #{custConsltNo}

UPDATE shopion.tOprCustConslt SET
ChnlCode = #{chnlCode}, ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE CustConsltNo = #{custConsltNo}
